add_task(async function test_getUrlForUriEws() {
  const service = Cc[
    "@mozilla.org/messenger/messageservice;1?type=ews"
  ].createInstance(Ci.nsIMsgMessageService);

  const ewsMessageUrl = service.getUrlForUri(
    "ews-message://name@localhost/some/folder",
    null
  );
  Assert.equal(ewsMessageUrl.scheme, "x-moz-ews", "ews-message -> x-moz-ews");

  const xMozEwsUrl = service.getUrlForUri(
    "x-moz-ews://name@localhost/some/folder",
    null
  );
  Assert.equal(xMozEwsUrl.scheme, "x-moz-ews", "x-moz-ews -> x-moz-ews");

  for (let i = 0; i < 2; i++) {
    const first = [...inboxFolder.messages][i];
    const listener = new MessageFetchListener();
    client.getMessage(listener, first.getStringProperty("ewsId"));
    const data = await listener.promise;
    Assert.equal(data, messages[i].toMessageString());
  }
}

class MessageFetchListener {
  QueryInterface = ChromeUtils.generateQI(["IExchangeMessageFetchListener"]);

  constructor() {
    this.promise = new Promise((resolve, reject) => {
      this._resolve = resolve;
      this._reject = reject;
    });
    this.scriptableStream = Cc[
      "@mozilla.org/scriptableinputstream;1"
    ].createInstance(Ci.nsIScriptableInputStream);
  }

  onFetchStart() {}

  onFetchedDataAvailable(inputStream) {
    const count = inputStream.available();
    this.scriptableStream.init(inputStream);
    this._data = this.scriptableStream.read(count);
  }

  onFetchStop(status) {
    if (status == Cr.NS_OK) {
      this._resolve(this._data);
    } else {
      this._reject(status);
    }
  }

